const container = document.getElementById('tagCloudContainer');

/*
{
  "tags": {{ GetTagCloudData.data }}
}
*/

// Eine vordefinierte Farbpalette für ein harmonisches Design
const colors = ['#1E40AF', '#3B82F6', '#10B981', '#6366F1', '#8B5CF6', '#EC4899', '#F59E0B'];
function renderTagCloud() {
  container.innerHTML = '';
  const tags = appsmith.model.tags || [];
  if (tags.length === 0) {
    container.innerHTML = '<p style="color: #9ca3af; font-size: 14px;">Keine Tags vorhanden</p>';
    return;
  }

  // Finde Min- und Max-Werte für die Berechnung der dynamischen Schriftgröße
  const values = tags.map(t => t.value);
  const minVal = Math.min(...values);
  const maxVal = Math.max(...values);
  const valRange = maxVal - minVal || 1;

  // Schriftgrößen-Grenzen definieren (in Pixeln)
  const minFontSize = 14;
  const maxFontSize = 38;
  tags.forEach((tag, index) => {
    const tagEl = document.createElement('span');
    tagEl.classList.add('cloud-tag');
    tagEl.innerText = tag.text;

    // Berechnung der proportionalen Schriftgröße
    const normalizedSize = (tag.value - minVal) / valRange;
    const fontSize = minFontSize + normalizedSize * (maxFontSize - minFontSize);
    tagEl.style.fontSize = `${fontSize}px`;

    // Weise dem Tag eine Farbe aus der Palette zu
    tagEl.style.color = colors[index % colors.length];

    // Optionaler Hintergrund-Effekt basierend auf der Wichtigkeit
    tagEl.style.backgroundColor = `rgba(0, 0, 0, 0.02)`;

    // Event-Trigger zurück an Appsmith senden, wenn ein Tag angeklickt wird
    tagEl.addEventListener('click', () => {
      appsmith.triggerEvent("onTagClick", {
        selectedTag: tag.text
      });
    });
    container.appendChild(tagEl);
  });
}

// Initialisierung bei Appsmith-Start und -Änderung
appsmith.onReady(() => {
  renderTagCloud();
  appsmith.onModelChange(() => {
    renderTagCloud();
  });
});

